use crate::*;
pub fn sources()->&'static Value{static DATA:OnceLock<Value>=OnceLock::new();DATA.get_or_init(||serde_json::from_str(include_str!("../data/architecture-sources.json")).unwrap())}
pub fn source(name:&str)->Value{sources()["references"].as_array().unwrap().iter().find(|r|s(r,"style")==name).unwrap_or(&sources()["references"][0]).clone()}
pub fn plan_name(name:&str)->String{format!("Catalog · {}",s(&source(name),"design"))}
pub fn default_stories(name:&str)->usize{if ["Contemporary","Cape Cod","Mid-century","Ranch"].contains(&name){1}else{2}}
pub fn default_bedrooms(name:&str)->usize{match name{"Mid-century"=>1,"Ranch"=>2,"Georgian"|"Modern farmhouse"|"Craftsman"|"Colonial"|"French country"=>4,_=>3}}
struct Plan{rooms:Vec<Room>,upper:bool,floor:usize}
impl Plan{
 fn new(c:&Config)->Self{Self{rooms:vec![],upper:c.active_floor>0,floor:c.active_floor}}
 fn add(&mut self,id:&str,name:&str,kind:&str,x:f64,z:f64,w:f64,d:f64){if w>=2.&&d>=2.{self.rooms.push(Room{id:format!("{}{}",id,floor_tag(self.floor)),name:name.into(),kind:kind.into(),x,z,w,d});}}
 fn cells(&mut self,x:f64,z:f64,w:f64,d:f64,count:usize,bed_start:usize,bath_last:bool){let mut at=z;let count=count.max(1).min((d/8.).floor().max(1.)as usize);for i in 0..count{let end=if i+1==count{z+d}else{z+grid(d*(i+1)as f64/count as f64)};let bath=bath_last&&i+1==count;let number=bed_start+i;self.add(&if bath{"bath-family".into()}else{format!("bed{}",number)},&if bath{"Family bathroom".into()}else if number==1{"Primary bedroom".into()}else{format!("Bedroom {}",number)},if bath{"bath"}else{"bedroom"},x,at,w,end-at);at=end;}}
}
// Each generated seed shifts the front/back room split a little so homes of the same style differ.
fn jitter(c:&Config)->f64{[0.,0.04,-0.04,0.07,-0.07][((c.seed/2+1)%5)as usize]}
pub fn layout(c:&Config)->(Vec<Room>,Value){let mut p=Plan::new(c);let(w,d)=(c.width,c.depth);if w<24.||d<24.||w*d<576.{small(c,&mut p)}else if c.stories==1{single(c,&mut p)}else if ["Georgian","Colonial","French country","Coastal"].contains(&c.home_style.as_str())&&w>=36.{formal(c,&mut p)}else{side_hall(c,&mut p)}for r in &mut p.rooms{if r.kind=="bedroom"&&(r.w<8.||r.d<8.||r.w*r.d<70.){r.kind="flex".into();r.name="Flexible room · enlarge for sleeping".into();}}if c.seed%2==1&&c.design_mode!="Blank slate"{for r in &mut p.rooms{r.x=w-r.x-r.w;}}foyer(c,&mut p.rooms);let reference=source(&c.home_style);let rooms=p.rooms;let out=json!({"rooms":rooms,"style":{"name":plan_name(&c.home_style),"description":reference["observed"]},"source":reference,"gridFeet":2,"catalogPlan":true,"foyer":rooms.iter().any(|r|r.kind=="foyer"),"bedrooms":rooms.iter().filter(|r|r.kind=="bedroom").count(),"baths":rooms.iter().filter(|r|r.kind=="bath").count(),"program":if c.active_floor==2{"Third floor · bedrooms, bath and flexible rooms"}else if c.active_floor==1{"Upper floor · bedrooms and family bathroom"}else if c.stories>=2{"Main floor · foyer, reception, kitchen and dining"}else{"Single floor · enclosed foyer, living and sleeping zones"},"note":"Deterministic source-informed adaptation. Nominal walls use a 2-foot grid. Dimensions, stairs, foyer, wood construction and roofs adapt the historic original; this is not an exact reconstruction or a permit-approved plan."});(rooms,out)}
fn single(c:&Config,p:&mut Plan){let(w,d)=(c.width,c.depth);let ratio=match c.home_style.as_str(){"Ranch"=>0.53,"Mid-century"=>0.65,"Cape Cod"=>0.50,"Contemporary"=>0.56,"Scandinavian"=>0.50,_=>0.52};let public=grid((w-6.)*ratio).clamp(8.,w-14.);let private=w-public-6.;let front=grid(d*(if c.home_style=="Cape Cod"{0.50}else if c.home_style=="Ranch"{0.57}else{0.56}+jitter(c))).clamp(8.,d-8.);p.add("reception","Reception gallery","hall",public,0.,6.,d);p.add("living",if c.home_style=="Victorian"{"Parlor"}else{"Living room"},"living",0.,0.,public,front);let kitchen=grid(public*if c.home_style=="Mid-century"{0.4}else{0.5}).clamp(4.,public-4.);if public<16.{p.add("kitchen","Kitchen & dining","kitchen",0.,front,public,d-front);}else{p.add("dining","Dining room","dining",0.,front,public-kitchen,d-front);p.add("kitchen","Kitchen","kitchen",public-kitchen,front,kitchen,d-front);}let beds=c.bedrooms.max(1);if beds==3&&d<32.&&private>=16.{let split=grid((d-4.)*0.5);let first=grid(private/2.);let x=public+6.;p.add("bed1","Primary bedroom","bedroom",x,0.,first,split);p.add("bed2","Bedroom 2","bedroom",x+first,0.,private-first,split);p.add("crosshall","Bedroom cross hall","hall",x,split,private,4.);p.add("bed3","Bedroom 3","bedroom",x,split+4.,private-8.,d-split-4.);p.add("bath-family","Family bathroom","bath",x+private-8.,split+4.,8.,d-split-4.);}else{p.cells(public+6.,0.,private,d,beds+1,1,true);}if c.bedrooms==0{for r in &mut p.rooms{if r.kind=="bedroom"{r.kind="flex".into();r.name="Study / flexible room".into();}}}}
fn side_hall(c:&Config,p:&mut Plan){let(w,d)=(c.width,c.depth);let wing=w-14.;let service_d=d-22.;let reverse_stair=c.home_style=="Victorian";let service_z=if reverse_stair{22.}else{0.};let stair_z=if reverse_stair{0.}else{d-16.};let landing_z=if reverse_stair{16.}else{d-22.};p.add("gallery",if p.upper{"Bedroom gallery"}else{"Reception gallery"},"hall",wing,0.,6.,d);p.add("stair","Switchback stair","stairs",wing+6.,stair_z,8.,16.);p.add("landing","Stair landing","hall",wing+6.,landing_z,8.,6.);if !p.upper{let front=grid(d*(match c.home_style.as_str(){"Victorian"=>0.4,"Craftsman"=>0.54,"Tudor"=>0.5,"English cottage"=>0.43,"Modern farmhouse"=>0.5,"Industrial"=>0.38,_=>0.46}+jitter(c))).clamp(8.,d-8.);p.add("living",if c.home_style=="Victorian"{"Front parlor"}else{"Living room"},"living",0.,0.,wing,front);if wing>=12.{p.add("kitchen","Kitchen & dining","kitchen",0.,front,wing,d-front);if service_d>=16.{p.add("pantry","Butler's pantry","flex",wing+6.,service_z,8.,service_d-8.);p.add("powder","Powder room","bath",wing+6.,service_z+service_d-8.,8.,8.);}else{p.add("pantry","Butler's pantry","flex",wing+6.,service_z,8.,service_d);p.rooms.iter_mut().find(|r|r.id=="kitchen").unwrap().d-=8.;p.add("powder","Powder room","bath",0.,d-8.,wing,8.);}}else{p.add("dining","Dining room","dining",0.,front,wing,d-front);if service_d>=16.{p.add("kitchen","Kitchen & pantry","kitchen",wing+6.,service_z,8.,service_d-8.);p.add("powder","Powder room","bath",wing+6.,service_z+service_d-8.,8.,8.);}else{p.add("kitchen","Kitchen","kitchen",wing+6.,service_z,8.,service_d);p.rooms.iter_mut().find(|r|r.id=="dining").unwrap().d-=8.;p.add("powder","Powder room","bath",0.,d-8.,wing,8.);}}}else{p.cells(0.,0.,wing,d,c.bedrooms.max(1),1,false);p.add("bath-family","Family bathroom","bath",wing+6.,service_z,8.,service_d.min(10.));p.add("linen","Linen / study","flex",wing+6.,service_z+10.,8.,service_d-10.);}if ["Victorian","Scandinavian"].contains(&c.home_style.as_str()){for r in &mut p.rooms{r.x=w-r.x-r.w;}}}
fn formal(c:&Config,p:&mut Plan){let(w,d)=(c.width,c.depth);let left=grid((w-20.)*if c.home_style=="French country"{0.43}else{0.5}).max(8.);let right=w-left-20.;p.add("gallery",if p.upper{"Upper west gallery"}else{"West reception hall"},"hall",left,0.,6.,d);p.add("gallery-right",if p.upper{"Upper east gallery"}else{"East reception hall"},"hall",left+14.,0.,6.,d);p.add("stair","Switchback stair","stairs",left+6.,d-16.,8.,16.);p.add("landing","Stair landing","hall",left+6.,d-22.,8.,6.);p.add("foyer-center",if p.upper{"Front landing"}else{"Entry gallery"},"hall",left+6.,0.,8.,6.);p.add("study-center",if p.upper{"Reading alcove"}else{"Library alcove"},"flex",left+6.,6.,8.,d-28.);if !p.upper{let split=grid(d*(if c.home_style=="French country"{0.4}else if c.home_style=="Coastal"{0.55}else{0.5}+jitter(c)));p.add("living","Formal living room","living",0.,0.,left,split);p.add("dining","Dining room","dining",0.,split,left,d-split);p.add("library",if c.home_style=="French country"{"Library"}else if c.home_style=="Coastal"{"Sitting room"}else{"Study"},"flex",left+20.,0.,right,split);p.add("kitchen","Kitchen","kitchen",left+20.,split,right,d-split-8.);p.add("powder","Powder room","bath",left+20.,d-8.,right,8.);}else{let beds=c.bedrooms.max(1);let a=(beds+1)/2;let b=beds-a;p.cells(0.,0.,left,d,a,1,false);p.cells(left+20.,0.,right,d,b+1,a+1,true);}}
fn small(c:&Config,p:&mut Plan){let(w,d)=(c.width,c.depth);if w<12.||d<12.{p.add("entry-foyer","Enclosed entry foyer","foyer",0.,0.,4.,4.);p.add("entry-storage","Entry storage","flex",4.,0.,w-4.,4.);p.add("studio","Compact studio","studio",0.,4.,w,d-4.);return}let front=grid(d*0.6).clamp(8.,d-4.);p.add("living","Living / sleeping studio","studio",0.,0.,w,front);p.add("kitchen","Kitchen","kitchen",0.,front,w-4.,d-front);p.add("bath","Bathroom","bath",w-4.,front,4.,d-front);}
pub fn foyer(c:&Config,rooms:&mut Vec<Room>){if c.design_mode=="Blank slate"||c.active_floor!=0||rooms.iter().any(|r|r.kind=="foyer"){return}let entry=rooms.iter().enumerate().filter(|(_,r)|near(r.z,0.)&&r.w>=4.&&r.d>=4.&&!["stairs","bath","bedroom","kitchen"].contains(&r.kind.as_str())).min_by(|(_,a),(_,b)|{let score=|r:&Room|if r.kind=="hall"{0.}else{100.}+(r.x+r.w/2.-c.width/2.).abs();score(a).total_cmp(&score(b))}).map(|(i,_)|i);let Some(i)=entry else{return};let r=rooms.remove(i);let fw=if r.kind=="hall"{r.w.min(6.)}else if r.w>=12.{6.}else{4.};let fd=if r.d>=12.{6.}else{4.};let right=rooms.iter().any(|q|q.kind=="hall"&&near(q.x,r.x+r.w));let fx=if right{r.x+r.w-fw}else{r.x};rooms.insert(i,Room{id:"entry-foyer".into(),name:"Enclosed entry foyer".into(),kind:"foyer".into(),x:fx,z:0.,w:fw,d:fd});let mut pieces=vec![];if fx>r.x{pieces.push((r.x,0.,fx-r.x,fd));}if fx+fw<r.x+r.w{pieces.push((fx+fw,0.,r.x+r.w-fx-fw,fd));}if fd<r.d{pieces.push((r.x,fd,r.w,r.d-fd));}for(j,(x,z,w,d))in pieces.into_iter().enumerate(){if w>=2.&&d>=2.{let mut part=r.clone();part.id=format!("{}-entry-return{}",r.id,j);part.x=x;part.z=z;part.w=w;part.d=d;rooms.insert(i+1+j,part);}}}
